   181  static struct RObject*
   182  packed_backtrace(mrb_state *mrb)
   183  {
   184    struct RData *backtrace;
   185    ptrdiff_t ciidx = mrb->c->ci - mrb->c->cibase;
   186    int len = 0;
   187    int size;
   188    void *ptr;
   189
   190    each_backtrace(mrb, ciidx, count_backtrace_i, &len);
   191    size = len * sizeof(struct backtrace_location);
   192    backtrace = mrb_data_object_alloc(mrb, NULL, NULL, &bt_type);
   193    ptr = mrb_malloc(mrb, size);
   194    backtrace->data = ptr;
   195    backtrace->flags = (uint32_t)len;
   196    each_backtrace(mrb, ciidx, pack_backtrace_i, &ptr);
   197    return (struct RObject*)backtrace;
   198  }
